CREATE TABLE IF NOT EXISTS production_gis_verification (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES gis_organizations(id) ON DELETE CASCADE, dataset_key text NOT NULL UNIQUE, source_phase integer NOT NULL, valid_geometry_count integer NOT NULL DEFAULT 0, open_exception_count integer NOT NULL DEFAULT 0, decided_exception_count integer NOT NULL DEFAULT 0, duplicate_group_count integer NOT NULL DEFAULT 0, certification_enabled boolean NOT NULL DEFAULT false, promotion_status text NOT NULL DEFAULT 'QUARANTINED', verified_at timestamptz NOT NULL DEFAULT now(), notes text NOT NULL DEFAULT 'Dataset remains quarantined until all GIS exceptions are resolved and certification is enabled.');